//! Glyph's data model and sync protocol.
//!
//! The server uses these types directly. The clients get them as TypeScript,
//! generated by `bun run gen:types` into `packages/types`.
//!
//! On the wire, field names are snake_case, the same as the database columns.

mod account;
mod glossary;
mod language;
mod model;
mod pair;
mod protocol;
mod rules;
mod translation;
mod user;

pub use account::{
    ChangePasswordRequest, CreateInviteRequest, CreatedInvite, Invite, InvitePreview, LoginRequest,
    MIN_PASSWORD, Me, MemberInfo, Role, SignupRequest, UpdateMemberRequest, UpdateProfileRequest,
    UpdateWorkspaceRequest, UserInfo, WorkspaceInfo, check_password, clean_name, normalize_email,
    url_key_from,
};
pub use glossary::{GlossaryEntry, GlossaryEntryCreate, GlossaryEntryPatch};
pub use language::{Language, LanguageCreate, LanguagePatch};
pub use model::{Actor, ModelKind, Validate, ValidationError, Write};
pub use pair::{LanguagePair, LanguagePairCreate, LanguagePairPatch};
pub use protocol::{
    ApiError, Bootstrap, Operation, ServerMessage, SyncAction, SyncEntry, Transaction,
    TransactionResult,
};
pub use rules::language_code;
pub use translation::{DEFAULT_NAMESPACE, HUMAN, Translation, TranslationCreate, TranslationPatch};
pub use user::User;
